using Microsoft.AspNetCore.Identity;
using Microsoft.EntityFrameworkCore;
using Identity.Models;

var builder = WebApplication.CreateBuilder(args);

builder.Services.AddDbContext<AppIdentityDbContext>(options =>
    options.UseSqlServer(
        builder.Configuration["ConnectionStrings:DefaultConnection"]));

builder.Services.AddIdentity<AppUser, IdentityRole>()
    .AddEntityFrameworkStores<AppIdentityDbContext>()
    .AddDefaultTokenProviders();

builder.Services.AddAuthentication()
    .AddGoogle(options =>
    {
        options.ClientId     = "YOUR_GOOGLE_CLIENT_ID";
        options.ClientSecret = "YOUR_GOOGLE_CLIENT_SECRET";
        options.SignInScheme  = IdentityConstants.ExternalScheme;
    });

builder.Services.AddControllersWithViews();

var app = builder.Build();
app.UseRouting();
app.UseAuthentication();
app.UseAuthorization();
app.MapControllerRoute(
    name: "default",
    pattern: "{controller=Account}/{action=Login}/{id?}");
app.Run();

using Microsoft.AspNetCore.Mvc;
using Microsoft.AspNetCore.Authorization;
using Microsoft.AspNetCore.Identity;
using Identity.Models;
using System.Security.Claims;

namespace Identity.Controllers
{
    [Authorize]
    public class AccountController : Controller
    {
        private readonly UserManager<AppUser>   userManager;
        private readonly SignInManager<AppUser> signInManager;

        public AccountController(
            UserManager<AppUser>   userMgr,
            SignInManager<AppUser> signinMgr)
        {
            userManager   = userMgr;
            signInManager = signinMgr;
        }

        [AllowAnonymous]
        public IActionResult GoogleLogin()
        {
            string redirectUrl = Url.Action(
                "GoogleResponse", "Account");

            var properties = signInManager
                .ConfigureExternalAuthenticationProperties(
                    "Google", redirectUrl);

            return new ChallengeResult("Google", properties);
        }

        [AllowAnonymous]
        public async Task<IActionResult> GoogleResponse()
        {
            ExternalLoginInfo info =
                await signInManager.GetExternalLoginInfoAsync();

            if (info == null)
                return RedirectToAction(nameof(Login));

            var result = await signInManager
                .ExternalLoginSignInAsync(
                    info.LoginProvider,
                    info.ProviderKey,
                    isPersistent: false);

            if (result.Succeeded)
            {
                string[] userInfo =
                {
                    info.Principal
                        .FindFirst(ClaimTypes.Name)!.Value,
                    info.Principal
                        .FindFirst(ClaimTypes.Email)!.Value
                };
                return View("GoogleResponse", userInfo);
            }

            AppUser user = new AppUser
            {
                Email    = info.Principal
                    .FindFirst(ClaimTypes.Email)!.Value,
                UserName = info.Principal
                    .FindFirst(ClaimTypes.Email)!.Value
            };

            IdentityResult identResult =
                await userManager.CreateAsync(user);

            if (identResult.Succeeded)
            {
                identResult = await userManager
                    .AddLoginAsync(user, info);

                if (identResult.Succeeded)
                {
                    await signInManager
                        .SignInAsync(user, isPersistent: false);
                    return RedirectToAction("Index", "Home");
                }
            }

            return View("Login");
        }

        public IActionResult Login(string returnUrl) => View();
        public async Task<IActionResult> Logout()
        {
            await signInManager.SignOutAsync();
            return RedirectToAction("Index", "Home");
        }
    }
}

